export const pages=[{"id": "PG01", "name": "登录与身份异常页", "basis": "F09、D11；R1"}, {"id": "PG02", "name": "全域态势总览", "basis": "F10；R2"}, {"id": "PG03", "name": "态势钻取与详情抽屉", "basis": "产品补全；R2"}, {"id": "PG04", "name": "新建搜索空态", "basis": "F01、F02；R1"}, {"id": "PG05", "name": "超级搜索执行工作台", "basis": "F01；R1"}, {"id": "PG06", "name": "搜索历史列表及筛选", "basis": "F01、F11；R1"}, {"id": "PG07", "name": "澄清与计划卡片", "basis": "F02；R1"}, {"id": "PG08", "name": "执行详情和工具详情抽屉", "basis": "F03；R1"}, {"id": "PG09", "name": "资金分析结果视图", "basis": "D09；R1"}, {"id": "PG10", "name": "人员轨迹结果视图", "basis": "D09；R1"}, {"id": "PG11", "name": "数据库表格图表与口径详情", "basis": "D02、D09；R1"}, {"id": "PG12", "name": "因案研判列表", "basis": "F07；R2"}, {"id": "PG13", "name": "案件研判详情工作台", "basis": "F07与新版适配；R2"}, {"id": "PG14", "name": "因事研判列表", "basis": "F06；R2"}, {"id": "PG15", "name": "因事任务创建与编辑向导", "basis": "F06；R2"}, {"id": "PG16", "name": "因事研判详情工作台", "basis": "F06与新版适配；R2"}, {"id": "PG17", "name": "案件串并候选与核验详情", "basis": "旧导航及产品补全；R3"}, {"id": "PG18", "name": "工作空间标签页", "basis": "F01、F03；R1"}, {"id": "PG19", "name": "文档空间及文件预览", "basis": "F01、F04；R1"}, {"id": "PG20", "name": "导图空间和关系详情", "basis": "F01、F04、F06；R1查看，R2编辑"}, {"id": "PG21", "name": "实体详情抽屉", "basis": "F04、F06；R1"}, {"id": "PG22", "name": "证据来源预览和引用定位", "basis": "F04；R1"}, {"id": "PG23", "name": "时间线与冲突详情", "basis": "F04；R1基础，R2深化"}, {"id": "PG24", "name": "报告编辑和版本预览", "basis": "D09、F04、产品补全；R1基础"}, {"id": "PG25", "name": "复核与导出确认", "basis": "产品补全；R1导出，R2复核"}, {"id": "PG26", "name": "我的申请和授权详情", "basis": "F08、F02；R2"}, {"id": "PG27", "name": "审批待办与审批详情", "basis": "F08；R2"}, {"id": "PG28", "name": "通知与任务更新面板", "basis": "产品补全；R1任务提示，R2集中管理"}, {"id": "PG29", "name": "用户组织权限入口", "basis": "F09、D11；R1"}, {"id": "PG30", "name": "工具目录与工具配置详情", "basis": "F08、D08、D11；R1"}, {"id": "PG31", "name": "项目及Agent配置版本", "basis": "D11、F08；R1受控配置"}, {"id": "PG32", "name": "业务审计与运行诊断", "basis": "D11及产品补全；R1"}, {"id": "PG33", "name": "经验候选与评测管理", "basis": "D05、D09、D10；R2治理"}, {"id": "PG34", "name": "Skills目录与版本详情", "basis": "D07、D11范围冲突；R3"}];
export const features=[{"id": "AUTH01", "name": "统一登录和会话有效性", "requirement": "P0。用户打开受保护页面，经IDAAS登录及EasyGateway JWT鉴权后进入原目标页面；原目标无权时进入可访问首页并说明原因。加载、超时、账号异常、无应用权限、终端不符必须分开呈现。密码不匹配、重复输错等旧版状态仅在实际部署采用密码登录时显示，R1不凭旧设计自建密码认证。令牌失效先暂停新请求，提示重新登录；登录恢复后重新拉取快照，不重发上一次工具动作。\n\n验收：深链无令牌不得显示敏感预览；过期后既不能下载文件，也不能通过SSE继续接收越权内容。对应AT01。"}, {"id": "AUTH02", "name": "组织与案件上下文", "requirement": "P0。关联案件仅从有权限的列表选择，显示案件名、编号脱敏值和数据范围。关联、切换、解除均显示影响说明；新任务使用新快照，历史任务保留原关联。组织切换前提示未保存草稿，切换后关闭旧SSE并清空旧组织缓存。当前执行不随导航自动取消，但旧组织内容不能继续展示。\n\n验收：切换组织或撤销权限后，浏览器返回和直接访问对象地址都不能恢复旧数据。对应AT02。"}, {"id": "AUTH03", "name": "角色与无权限体验", "requirement": "P0。入口按角色可见，服务端对每次查询、操作、下载复核权限。用户无权时显示“当前无访问权限”及申请路径，不回传敏感字段再由前端遮罩。不存在与无权限可统一错误外观以避免对象枚举；审计日志保留真实原因。\n\n验收：平台管理员角色不自动获得案件正文读取权。对应AT01、AT23。"}, {"id": "SIT01", "name": "指标总览", "requirement": "P0。至少覆盖已授权警情数量、时段变化和地域/类别分布，具体指标字典由业务和数据负责人确认。每项指标显示统计单位、时间范围、数据源、刷新时间及缺口；同比环比的分母、时区、去重规则必须可查。无同期数据不输出0%或无限增长。\n\n验收：筛选改变后同一快照内各图表口径一致；加载失败不保留旧数字却标成新筛选结果。对应AT03。"}, {"id": "SIT02", "name": "钻取和带条件研判", "requirement": "P0。点击指标或图表进入PG03，承接全部条件，明细列表支持分页与来源查看；点击“发起研判”进入PG04并预填可读问题、过滤条件与快照引用。用户确认发送前不执行工具、不消耗授权查询。禁止把前端选中的数据全集直接粘贴进Prompt。\n\n验收：从钻取到新任务，时间、地域、类别可在输入确认区核对，权限按任务创建时重新计算。对应AT03、FL01。"}, {"id": "SIT03", "name": "收藏视图与空异常", "requirement": "P1。可保存筛选而非保存一份永久实时结论；收藏进入时重新取数并展示时间。零记录、无数据源、接口失败、无权限分开。地图或地域数据不可用时降级为表格，不用默认坐标伪造分布。\n\n验收：过期视图必须显式标记，导出时附当前有效范围。对应AT03。"}, {"id": "SRCH01", "name": "创建会话与发送", "requirement": "P0。输入文本、可选附件、可选案件上下文后发送；服务端校验身份、范围、输入长度及附件就绪状态，返回会话、主任务和消息标识。前端以client_request_id避免重复点击产生两次任务。标题先用可读摘要，用户可修改，不以标题作为唯一键。长度上限由模型及产品共同配置并在前端展示剩余限制。\n\n验收：双击发送只建立一次任务；服务端未确认创建时不能显示已运行；失败保留输入可重试。对应AT04。"}, {"id": "SRCH02", "name": "历史检索与管理", "requirement": "P0。PG06按标题/关键词、创建时间、案件上下文、状态筛选；结果显示标题、最近更新时间、最近任务状态和归属。支持重命名、归档和恢复；R1默认不提供物理删除。搜索范围只包含当前用户可见会话。归档运行中的会话仅改变列表展示，不默默取消任务。\n\n验收：筛选返回后条件与分页保留；失去案件访问权时历史正文及搜索摘要同步受限。对应AT05。"}, {"id": "SRCH03", "name": "多轮追问和上下文选择", "requirement": "P0。上一任务结束后可追问，显示将沿用的案件、文件和结论引用；用户可移除可选附件引用，不能移除强制授权范围。新一轮生成新Task并记录父任务引用，不覆盖上一任务。代词无法唯一指向实体时先澄清；不把更早会话中的同名对象自动代入。\n\n验收：用户询问“继续查他”且存在多个对象时不直接查询任何一个。对应AT06。"}, {"id": "SRCH04", "name": "输入草稿和离开页面", "requirement": "P0。运行中发送禁用但草稿可编辑；切页不终止后台执行，返回后先读快照再订阅增量。草稿本地持久化是否允许依终端安全策略决定，默认不落持久磁盘；刷新可能丢失时提前提示。退出登录清理临时缓存。\n\n验收：运行态、中文IME、换行、空文本、断网后输入保留及焦点均通过键盘测试。对应AT04、AT25。"}, {"id": "SRCH05", "name": "简单问答分流", "requirement": "P0。通用解释类问题可走SimpleLLMExecutor直接响应；只要涉及受保护业务事实，仍须授权数据来源，不能因“简单问题”绕开权限。直接响应不展示伪造规划步骤和工具调用。无引用的通用说明明确不是检索结果。\n\n验收：询问术语可直接回答；询问特定对象是否有警情时必须进入授权查询链路。对应AT06、FL02。"}, {"id": "PLAN01", "name": "必要澄清", "requirement": "P0。系统检查目标、实体唯一性、时间、地域、数据源、口径和输出要求；只询问影响执行或结论的缺项，避免所有问题机械走表单。支持选项与补充文字；用户提交后展示确认摘要。未明确时间时可提出默认建议，但必须显式确认或在可低风险场景标出采用值。\n\n验收：用户改变时间范围后，计划、工具参数和报告范围一致；取消澄清保留草稿，不开始采集。对应AT07。"}, {"id": "PLAN02", "name": "计划生成与确认", "requirement": "P0。展示目标、步骤、依赖、预期数据源、预期产物和可能的权限缺口；只展示可审计执行摘要，不展示原始思维链。计划可以自动进入低风险已授权执行，或按策略要求确认；交互必须说明当前是否等待用户确认。执行前更改需求生成新plan_version。\n\n验收：列表顺序不替代依赖约束；未满足依赖的步骤不能先运行。对应AT08。"}, {"id": "PLAN03", "name": "计划调整与范围变更", "requirement": "P1。执行中不允许直接拖拽节点改运行DAG；用户点击“调整需求”先提出变更，再由服务端在安全边界停止或完成当前动作，生成新版本并确认。已产出的数据可按范围与时效复用，复用项及失效项可见。自动重规划必须说明原因和新增范围；扩大访问范围必须重新授权。\n\n验收：范围扩大后不能复用旧授权；旧计划可回溯但不继续响应新版步骤按钮。对应AT12。"}, {"id": "PLAN04", "name": "进度和可解释性", "requirement": "P0。任务总进度从实际执行快照计算。默认完成步骤数/当前有效步骤数，失败和取消不计成功完成；重规划导致分母变化须说明。并行步骤不以耗时比例冒充业务完成度。F01示例四步完成一步显示1/4与25%；无步骤可计算时仅显示阶段，不假造百分比。\n\n验收：前端计时器不改变进度；Agent阶段性发现标为“待核验”，不得提前宣布后续步骤已完成。对应AT08。"}, {"id": "EXEC01", "name": "执行轨迹与工具详情", "requirement": "P0。工具卡显示名称、版本、状态、起止时间、可见范围内参数摘要、输出对象引用和错误类别。流式文本标为生成中，只有服务端提交完成结果后才形成最终消息。Agent卡按角色展示活动及阶段性产物，不把每个工程类都当一个业务Agent。\n\n验收：大结果只展示preview和按需分页，原始数据通过授权对象访问；不得一次渲染百万行。对应AT09、AT16。"}, {"id": "EXEC02", "name": "停止与终止", "requirement": "P0，接口语义待DEC03确认。运行中点击停止出现影响说明：已完成产物保留；后续未启动动作取消；外部在途动作可能无法撤回。确认后进入“停止请求处理中”的UI标记，按钮防重复。收到后端确认后才显示终止结果。不能终止的外部动作继续标“等待外部完成”，并禁止继续派生任务。\n\n验收：停止与完成同时发生时以服务端事件顺序为准；新任务只能在无活跃执行锁时发送。TaskState原枚举不被前端擅加CANCELED。对应AT10。"}, {"id": "EXEC03", "name": "失败与局部重试", "requirement": "P0。按暂时不可用、权限、输入错误、无数据、校验失败分流；无数据不是执行失败。重试同一目标、同一计划节点并产生新attempt，不覆盖旧记录；自动重试次数与退避由工具策略配置。对有外部副作用的动作，必须先确认幂等或查询外部状态，不盲目重试。\n\n验收：重试不重复生成业务动作；可回查每次失败原因、参数版本和产物。对应AT11。"}, {"id": "EXEC04", "name": "暂停与恢复", "requirement": "P1，R2建议。只在执行器具备检查点及动作可挂起语义时提供。暂停不等于取消，恢复要再次验证权限、配置兼容及数据时效。不可暂停的外部调用可完成后停在安全边界。刷新或重新登录不得自动触发恢复。\n\n验收：不支持检查点的任务不出现可点击暂停按钮；过期授权下恢复被拒绝。对应AT12。"}, {"id": "EXEC05", "name": "校验与部分成功", "requirement": "P0。将覆盖、时效、来源、逻辑及统计校验显示为结构化结果；可计算事实优先由确定性规则核验。无法补齐时输出“部分成功”及具体未完成目标，不包装成完整成功。保留已验证产物，不能失败一次就清空所有成果。\n\n验收：要求三个月但只得到七天时，报告范围与缺口必须明确，禁止输出三个月完整结论。对应AT13。"}, {"id": "EXEC06", "name": "断线重连和多端一致", "requirement": "P0。网络断开标明“连接中断，后台可能仍在执行”，不显示任务失败；恢复先获取权威快照，再接收可重放增量。事件去重、按序应用，检测缺口重新同步；任务状态由服务端决定。多个标签页重复打开不创建新执行。\n\n验收：刷新、事件重复、乱序、丢失后，任务树、进度和最终产物一致，详见事件合同。对应AT14。"}, {"id": "FUND01", "name": "对象与资金数据采集", "requirement": "P0。输入经确认的人员、账户或支付账号、时间范围和授权用途；选择已有产物或授权RPA工具采集。展示账号类型、数据源、覆盖区间、采集状态、记录数及缺失字段。资金账户作为实体类型需要新增F04组件变体，不能临时用人员卡替代。\n\n验收：超出授权日期的请求在服务端拒绝；部分账户未返回时列出缺口，不算作零流水。对应AT15。"}, {"id": "FUND02", "name": "交易整理与统计", "requirement": "P0。保留原始记录，派生标准字段包括交易时间及时区、金额、币种、收付方向、账户与对手方、来源记录标识。重复、撤销、冲正、空金额按明确规则处理；不同币种不直接相加，无已批准汇率口径则分别展示。输出收入、支出、净额及对手方统计，统计数字可下钻到贡献记录。\n\n验收：抽样交易与汇总可重算一致；不能用去重后的数量匹配未去重金额。对应AT15。"}, {"id": "FUND03", "name": "模式识别与多跳追踪", "requirement": "P0。围绕集中转入分散转出、短时频繁往来、共同对手方、资金多跳路径等生成可核验线索；阈值、观察窗口和层数由场景配置明示。进一步采集需重新检查账户范围和授权。交易关联、特殊消费或交通消费仅形成线索，不直接证明人员同行或到访。\n\n验收：每条路径可展开逐笔来源；达到工具限制时提示截断层数和未覆盖分支。对应AT15、AT18。"}, {"id": "FUND04", "name": "资金报告与继续研判", "requirement": "P0。报告包含目标、时间范围、来源、收支摘要、重点交易、关联方、路径、假设及缺口。选中交易可定位来源、加入报告、查看对手方或基于其发起新任务；新增对象采集不能在用户仅打开详情时自动触发。\n\n验收：报告中的表格、图和结论引用同一产物版本；“建议核查”不变成冻结执行命令。对应AT20、FL05。"}, {"id": "PERSON01", "name": "身份确认与关系背景", "requirement": "P0。支持已授权人员基本信息、户籍或同案关系等信息查询；身份证件、手机号等敏感字段按权限脱敏。不同来源存在同名、号码复用或身份冲突时，候选列表要求确认，不自动合并。关系页面区分来源事实和用户标注。\n\n验收：姓名相同但稳定标识不同的记录不自动归为同一人。对应AT17。"}, {"id": "PERSON02", "name": "轨迹采集与标准化", "requirement": "P0。按实际接入的铁路、航空、住宿、寄递、物流等来源建立事件列表；界面只显示可用授权连接器，不把示例中的通信关联当作已接入能力。事件保存原始时间、时区、地点精度和来源，未知时间或地点明确留空，不补造精确坐标。\n\n验收：日期精度记录不展示为某一秒；时区差异可解释；来源失败与无记录分开显示。对应AT17。"}, {"id": "PERSON03", "name": "时空分析和冲突", "requirement": "P0。提供时间排序、重复线索归并、同地点聚集、可能同行或关联等分析，均附条件和依据。跨来源时间冲突、异常速度或身份不一致标记为待核验，不自动删去不符合假设的数据。可能位置仅作为历史数据推断，不显示为实时确认位置。\n\n验收：轨迹冲突能展开两端来源；支持反证与未验证引用并列，不只呈现支持结论的数据。对应AT17、AT18。"}, {"id": "PERSON04", "name": "人员结果与扩展", "requirement": "P0。输出身份确认状态、事件摘要、轨迹与关系、覆盖范围、关键缺口和下一步核查建议。点击事件定位原始来源；关注实体加入工作空间；发起新对象查询须经确认。未经实际连接器与专门授权，不提供“立即查实时位置”的可用按钮。\n\n验收：来源撤权后，地图提示及侧栏缓存不能泄露原始位置。对应AT02、FL06。"}, {"id": "DB01", "name": "意图与指标口径", "requirement": "P0。确认统计对象、时间字段、地域字段、分类、去重键和比较范围。先读取真实可授权schema，再生成查询；不在PRD中虚构正式表名及关联键。遇到“最近”“高发”“重复警情”等含糊术语时澄清，或展示已批准指标字典定义供确认。\n\n验收：不存在的字段不得靠模型猜测后执行；查询范围可在结果页回看。对应AT19。"}, {"id": "DB02", "name": "只读查询与执行控制", "requirement": "P0。生成SQL后做语法、只读、对象白名单、字段权限、扫描规模与超时检查；DB账号最小权限，仅允许经批准的查询。禁止模型执行写入、DDL或多语句绕过。服务端限制结果大小、分页与并发，超限提供缩小范围建议，不返回截断结果却称完整。\n\n验收：用户提示“忽略限制执行删除”或附件中夹带SQL指令均不能触发写操作。对应AT19、AT24。"}, {"id": "DB03", "name": "结果核验和可视化", "requirement": "P0。核验总计、分组加总、分母、连接重复、空值和去重；解释数据延迟与时间窗口。自动图表必须与表格同源，使用明确单位与刻度。查询返回0行时说明在指定来源和条件下未检出，不推断现实不存在相应事实。\n\n验收：SQL成功但口径错误时不能输出“已校验”；图表筛选不会仅改标题不改数据。对应AT19。"}, {"id": "DB04", "name": "查询复用与继续分析", "requirement": "P1。保留问题、标准化口径、SQL版本、数据源版本、执行时间和结果产物引用。保存的是查询定义和版本，不保证未来结果相同。追问“按区域拆分”生成新的查询记录，并提示沿用时间与去重口径；重新执行前重新授权。\n\n验收：历史查询可回看当时结果，重新执行后生成新版本并标记差异。对应AT19、FL07。"}, {"id": "CASE01", "name": "因案列表与进入", "requirement": "P0。PG12布局：B区检索、案件状态/类别/组织/时间筛选及可用导入入口，C区列表含案件名称、编号脱敏、负责人、更新、研判任务数、业务状态和操作，D区可选案件摘要。案件主数据由正式案件系统同步或受控引用，接入方式待DEC06；不得自行给外部案件变更立案状态。\n\n验收：用户仅看到被授权案件，列表数量与可见范围一致；没有案件源时显示未接入而非假数据。对应AT21。"}, {"id": "CASE02", "name": "案件详情与发起任务", "requirement": "P0。PG13顶部为案件摘要和权限范围；主体包含研判任务、实体线索、资料、成果及操作记录；发起任务时可选择已有材料并预填案件范围，进入复用工作台。多个任务可并存，某次执行失败不把整个案件状态改为失败。\n\n验收：从案件发起的搜索必须有显式来源入口和返回案件路径，不能误改模块归属。对应AT21、FL15。"}, {"id": "CASE03", "name": "成员与成果关联", "requirement": "P1。负责人在授权范围内选择协作者；邀请只赋予案件工作空间角色，不自动赋予外部数据源查询权。已有报告关联案件时检查对象范围及归属，保留原任务和报告版本引用。解除关联只改变关系，不删除原始产物。\n\n验收：协作者打开报告时引用逐项鉴权；未授权的附件不可被通过报告下载绕过。对应AT02、AT21。"}, {"id": "EVENT01", "name": "因事列表与筛选", "requirement": "P0。PG14继承旧版任务名称、类型、状态、初始实体、创建人、组织、创建时间、操作列；B区为名称检索、组合筛选、重置、保存筛选和新建。列表同时提供业务任务状态和最近执行状态，不能只用同一个“进行中”混淆两者。更新徽标指向真实变更时间，不模拟未读数量。\n\n验收：保存筛选只保存条件；历史状态更新后列表不展示过期的运行态。对应AT22。"}, {"id": "EVENT02", "name": "因事创建向导", "requirement": "P0。PG15包含三步：基本信息、实体线索、采集工具。第一步任务名、类型必填，创建人和组织自动只读；名称重复允许时以唯一ID区分，是否要求组织内同名限制待业务确认。第二步选择新增/已有实体、实体类型与角色；是否已立案控制案件编号字段，未立案不强制虚填案件号；网络账号可补平台、用途、商户信息。第三步展示工具的可用性、授权范围及所需参数。\n\n旧稿“最多5个初始实体”作为初始设计限制保留，参数应可配置，超过时说明限制而非静默丢弃。实体角色如被害人、嫌疑人、关联人仅为有来源的业务属性，不由模型自动定性。每一步前进校验并保存草稿；点击完成后创建业务任务，再由用户确认是否立即执行采集。\n\n验收：回退不丢数据；未立案与已立案分支正确；无权限工具不能因完成向导而被执行。对应AT22、FL16。"}, {"id": "EVENT03", "name": "详情与资料采集", "requirement": "P0。PG16上方任务摘要，下方任务执行、实体图谱、资料结果和研判记录；实体详情含基础信息、采集建议、研判笔记、结果分析。每次采集展示开始/结束时间、状态及输出文件；重新采集产生新批次，并保留历史。编辑已开始任务只允许可变元信息；目标、实体或时间范围变化必须生成新执行或变更版本。\n\n验收：用户在运行中改实体名称不影响稳定ID；改实体身份标识触发重校验，不能悄悄改变在途请求。对应AT22。"}, {"id": "EVENT04", "name": "人工图谱与研判笔记", "requirement": "P1。支持从实体发起授权查询、手工添加实体、补充关系和笔记；“置灰”在本稿定义为当前视图弱化显示，不等同于删除或排除算法输入。排除分析必须单独操作、说明原因且形成范围版本。旧稿添加子节点、刷新、交易标签能力按统一导图规则迁移。\n\n验收：隐藏节点不导致报告结论改变；删除手工关系可审计并可从版本恢复。对应AT18。"}, {"id": "SERIAL01", "name": "案件串并候选", "requirement": "P0，R3。PG17左侧筛选案件/时间/关系类型，中间候选案件对及关联理由，右侧证据对照；候选来自明确的可授权案件集合。规则阈值与模型相似度分开展示，不提供无定义“关联概率”。无权限案件只提示存在受限关联线索或完全隐藏，展示策略须安全评审，不暴露案名或对象。\n\n验收：共用手机号或同名不能直接自动串案；每一候选均有可读理由和反证检查。对应AT26。"}, {"id": "SERIAL02", "name": "串并核验和成果", "requirement": "P0，R3。研判人员查看两侧来源，标记待核验、建议关联、排除；负责人复核后形成“串并研判意见”，而非自动修改正式案件关系。排除须填写理由并保留版本。需要向正式案件系统提交时走独立权限和确认流程，未接入时仅允许导出意见。\n\n验收：审批串并意见和正式合并案件是不同操作，报告不能越权改案件主数据。对应AT26、FL17。"}, {"id": "SPACE01", "name": "执行与关注总览", "requirement": "P0。PG18从上到下为任务概览、主子任务与Agent树、关注实体、近期产物；点击任务定位中栏对应执行卡，点击文件切换PG19，点击实体打开PG21。选中、运行与焦点样式独立。任务层级过深采用折叠和面包屑，不无限缩小字号。\n\n验收：左计划、中间过程、右树同一task_id状态一致；切标签不重新执行。对应AT09。"}, {"id": "SPACE02", "name": "产物目录和预览", "requirement": "P0。PG19展示名称、类型、来源任务、生成时间、大小、版本和Ready/Processing/Error；可按任务、类型和时间筛选。预览支持已接入类型的文本、报告、表格与图片基础查看；F04具有音频变体不代表已经有转写能力。未知或不可预览格式显示元信息，授权后下载，不显示解析成功。\n\n验收：大表分页/虚拟化，原始文件与派生结果标识清晰，文件名相同不覆盖原始对象。对应AT16。"}, {"id": "SPACE03", "name": "上传和解析", "requirement": "P0。用户选择文件后显示大小、格式校验和上传进度，上传完成后进入安全检查与解析；解析未就绪时不能当作可用证据。格式白名单、大小、页数、编码、压缩包及恶意内容检测策略由后端配置并前端展示。R1优先支持经评审的结构化表和文本文件；OCR、ASR等按连接器能力显式开启，不由图标推断。\n\n验收：上传成功解析失败有独立状态和可重试入口；重复上传提示复用或新版本，文件内容中的指令不能覆盖系统规则。对应AT16、AT24。"}, {"id": "SPACE04", "name": "血缘和访问控制", "requirement": "P0。每份产物记录来源任务、动作、数据源、采集时间、查询范围、转换版本及校验值；原始产物不可被编辑覆盖。点击来源链逐级回溯，权限按当前访问校验。移动到案件仅改变关联，不改变原始授权和归属。\n\n验收：报告的派生表能回到输入对象及转换记录；复制引用不能绕过字段脱敏。对应AT16、AT23。"}, {"id": "SPACE05", "name": "归档与销毁边界", "requirement": "P1。用户可从个人视图归档产物或解除关联；仍被报告引用时提示影响并保留引用记录。物理删除按保留与合规策略执行，不提供普通用户一键永久销毁。软删除后的历史版本、缓存、下载链接处理需统一契约。\n\n验收：归档不破坏已提交报告的来源说明；真正删除后不能通过旧下载链接继续访问。对应AT23。"}, {"id": "DATA01", "name": "实体详情与标识", "requirement": "P0。支持Person、Organization、Location、Vehicle、Phone；为资金和网络线索新增账户、网络账号变体待设计补齐。详情分基础属性、来源、关系、事件、相关产物和人工笔记；字段显示来源和更新时间。同名提示可疑重复，但实体合并需稳定标识、用户确认和可回滚版本。\n\n验收：不同来源的冲突属性并列显示，不默默“取最新”覆盖全部事实。对应AT17、AT18。"}, {"id": "DATA02", "name": "证据引用与原文定位", "requirement": "P0。结论后引用可点击，PG22显示来源名称、类型、采集时间、任务、定位锚点、原文片段和权限。文档按页/段，表格按行/记录主键，数据库按查询和记录定位；定位信息失效时显示整份可授权来源及失效说明，禁止伪装精确定位。Supporting、Contradicting、Unverified是相对于某项结论的关系，不是全局永久标签。\n\n验收：引用打不开时不显示“已核验”；同一证据可支持A结论并反对B结论。对应AT18、FL12。"}, {"id": "DATA03", "name": "关系图和路径追踪", "requirement": "P0查看，P1编辑。区分交易、亲属、共同出现等关系类型，支持方向、时间过滤、层级展开、选中路径和来源定位。强、中、弱必须附定义和生成依据；没有定义时仅显示关系类型与来源数量，不展示误导分值。大图分层加载，显示已展示节点数与总数或“总数未知”。\n\n验收：仅筛选时间后，节点和边依据同步变化；隐藏节点不删除数据；自动布局改变不影响证据关系。对应AT18。"}, {"id": "DATA04", "name": "人工补录与修改", "requirement": "P1，R2。手工添加必须标“人工录入”，记录录入者、时间、依据及核验状态。关系编辑、实体合并、排除分析产生版本；对自动生成结果的纠正不能直接改原始来源。并发编辑用版本冲突提示，禁止最后写入者静默覆盖。\n\n验收：没有来源的人工关系可保存为待核验，但不能自动成为报告已证实事实。对应AT18、FL13。"}, {"id": "DATA05", "name": "时间线和冲突核验", "requirement": "P0基础。时间线支持Normal、Key、Conflict、Incomplete及首中末连接样式，业务过滤包括实体、来源、事件类型、日期。缺失事件边界用不确定区间显示，冲突详情并排原始来源；人工标记已核验附理由，不删除原冲突记录。\n\n验收：日期精度、时区及未知区间可见；冲突被人工处理后仍可回查历史。对应AT17。"}, {"id": "REPORT01", "name": "生成结构化报告", "requirement": "P0。至少包含目标、对象及权限范围、数据与时间、处理方法摘要、关键事实、研判推断、支持与矛盾引用、缺口、建议、产物清单及版本。资金、人员、数据库采用同一基础结构加场景章节。失败任务可生成“执行情况说明”，不得冠以完整研判报告。\n\n验收：每个关键数字及业务事实可追溯；无依据文本明确标为假设或删除。对应AT20。"}, {"id": "REPORT02", "name": "编辑与版本", "requirement": "P0。用户编辑形成新版本，区分系统生成与人工修改。修改事实或删除引用时提示重新核验；手工文本不因保存而自动获得已复核标记。版本比较可查看新增删除与引用变化；并发保存需版本校验。\n\n验收：重新生成不覆盖人工最终稿；引用编号重排后仍指向正确来源。对应AT20。"}, {"id": "REPORT03", "name": "人工复核", "requirement": "P1，R2。报告状态建议Draft、InReview、ChangesRequested、Reviewed、Archived，与TaskState独立。提交时冻结待复核版本，复核人员查看来源、覆盖、矛盾和敏感字段；通过或退回均记录意见。修改已复核版本生成新草稿并使新版本需要重新复核，原通过版本保留。\n\n验收：作者不能仅通过前端接口把草稿改为已复核；复核不代表自动形成业务处置结论。对应AT20、FL14。"}, {"id": "REPORT04", "name": "导出与分发", "requirement": "P0。先选择范围、格式和脱敏策略，再展示文件列表、收件范围或本地下载、敏感级别和用途确认；服务端再次鉴权并生成带版本、生成者、时间、范围的导出文件。R1建议支持PDF报告和受控CSV表格，Word等格式按业务确认；此处为产品导出能力，不是本PRD交付格式承诺。\n\n导出大文件异步生成，失败可重试而不重复计费或建重复批次；链接短期有效且下载时再鉴权。表格导出需防公式注入。系统不得把隐藏敏感列写入导出文件。\n\n验收：页面脱敏、预览和导出一致；导出事件记录报告/产物版本、操作者、范围和结果。对应AT20、AT23。"}, {"id": "APPROVE01", "name": "权限缺口识别", "requirement": "P0。动作执行前校验授权，缺口说明资源类别、目的、范围、时效及阻断步骤，不泄露未授权数据。R1提供外部申请指引或既有系统入口；恢复后用户重新确认，后端重新检查实际授权。没有接入时不显示“申请成功”或虚假倒计时。\n\n验收：拒绝后不自动换另一工具规避相同授权限制。对应AT23。"}, {"id": "APPROVE02", "name": "申请与我的申请", "requirement": "P0，R2。PG26列表含申请对象、范围、理由、提交时间、审批状态和关联任务；详情保留一次性授权、期限与当前有效状态。建议申请状态Submitted、Approved、Denied、Expired、Withdrawn；这些是申请域新枚举，不改Action原状态。重复提交同一未决范围提示已有申请。\n\n验收：审批通过不等于永久权限，过期或撤回时关联动作必须重新验证。对应AT23、FL08。"}, {"id": "APPROVE03", "name": "审批决策与恢复", "requirement": "P0，R2。PG27上部申请摘要，中部范围和理由，下部通过/拒绝及意见；通过可缩小范围但不可无提示扩大。拒绝必须说明原因。审批决定仅更新授权事实，Action能否恢复取决于任务未终止、授权有效和检查点可恢复；默认通知用户确认继续，自动恢复只能由明确策略允许。\n\n验收：任务终止后迟到的审批通过不会启动新动作；审批操作幂等且有审计。对应AT23。"}, {"id": "NOTIFY01", "name": "更新和待办", "requirement": "P1。PG28展示任务完成/失败、待澄清、待授权、报告复核和导出就绪等事件，按任务聚合去重。通知只显示可见范围内摘要，点击重新鉴权后进入对应页面。未读是阅读状态，不是任务状态；已读不自动批准或恢复。\n\n验收：同一完成事件重放不会产生两条未读；权限撤销后旧通知正文不再暴露敏感内容。对应AT14、AT23。"}, {"id": "ADMIN01", "name": "用户组织与角色映射", "requirement": "P0。PG29展示IDAAS同步状态、用户所属组织、角色和应用授权入口；创建、禁用、重置密码等旧版能力优先跳转主系统或通过受控同步接口执行，不在本地独立维护冲突主数据。用户被禁用或组织权限变化后使访问令牌与相关缓存按策略失效。\n\n验收：业务系统本地角色不能覆盖IDAAS禁用状态；同步失败显式显示最后成功时间。对应AT01、AT27。"}, {"id": "ADMIN02", "name": "工具目录和接入", "requirement": "P0。PG30列表展示工具名、类型、版本、所属Toolkit、环境、可用状态、健康状态和授权要求；详情维护输入输出schema、同步/异步/MCP方式、超时、重试、幂等、脱敏及数据分类。凭据仅在安全凭据存储引用，不写到Prompt或前端配置回包。测试必须使用隔离环境和脱敏样例。\n\n验收：缺失输入schema或副作用声明的工具不能发布；禁用阻止新动作，不假装撤回已经提交外部系统的请求。对应AT27。"}, {"id": "ADMIN03", "name": "项目与Agent配置", "requirement": "P0。PG31按ProjectConfig → AgentConfig → ToolkitConfig → ToolConfig组织，编辑模型、Prompt版本、允许工具和执行策略。发布生成不可变版本；运行任务锁定配置快照，管理员更新不影响在途任务。具备变更说明、校验、灰度或受控启用、回滚和审计；具体环境发布审批待部署治理确认。\n\n验收：Agent配置允许某工具仍不代表当前用户获授权；回滚只影响新任务或明确迁移任务。对应AT27、FL19。"}, {"id": "ADMIN04", "name": "审计和诊断", "requirement": "P0。PG32支持按用户、组织、案件、session/task/run/action、工具、时间、结果检索。区分业务审计与技术日志，查看敏感内容需要额外权限。日志包括谁、何时、出于何种用途、访问何范围、执行结果、权限决策和关联链，不记录原始密码、token或完整模型思维链。\n\n验收：从导出记录能回溯任务与来源；无法修改既往审计事件；普通研判人员不能读取他人诊断原始输入。对应AT23、AT27。"}, {"id": "MEMORY01", "name": "会话和用户偏好", "requirement": "P1。短期执行记录、会话摘要、用户偏好、领域经验按作用范围隔离。用户偏好只保存非敏感的展示或输出偏好；案件事实不得未经审查升级为跨用户记忆。D09、D10中的记忆层编号不完全一致，实现以前须统一命名和持久化边界。\n\n验收：新用户、新组织不能召回他人案件摘要；清除偏好不误删原始任务审计。对应AT24。"}, {"id": "MEMORY02", "name": "经验候选和评测", "requirement": "P1，R2。PG33从成功执行、失败纠正、人工反馈产生候选经验；记录来源、适用范围、脱敏情况、版本、评测与审核。只有审核通过且适用的经验可参与检索，效果退化可下线。候选经验不直接改系统Prompt，也不表示实时训练基础模型。\n\n验收：含真实身份信息的候选无法进入公共经验；下线后新任务不召回，历史执行仍保留版本引用。对应AT24、FL20。"}, {"id": "SKILL01", "name": "技战法能力包", "requirement": "P0，R3。PG34目标包含目录、适用条件、步骤、工具依赖、版本、测试、发布、停用和调用记录。D09示例有list_skills/load_skill，但D11 pp2、11明确本期不做；R1可使用已审定Prompt/经验实现有限复用，不伪装成完整Skills平台。\n\n验收：未发布或依赖工具不可用的能力包不可执行；权限以调用者上下文重新检查。对应AT28。"}];
export const flows=[{"id": "FL01", "name": "态势发现到新研判", "requirement": "前置：具有指标和明细权限。PG02设置时间地域 → 系统同步刷新指标并显示快照时间 → 用户点击异常变化 → PG03承接筛选显示明细和口径 → 用户点发起研判 → PG04预填问题及快照引用 → 用户确认发送 → 生成Task进入PG05 → 完成后可返回原态势条件。失败：指标过期则先刷新或明确使用历史快照；明细无权限不传敏感数据；取消发送不建立执行。"}, {"id": "FL02", "name": "简单问答", "requirement": "前置：身份有效。PG04输入通用解释问题 → SRCH05识别不需业务工具 → 显示流式回答 → 服务端提交最终消息 → 输入恢复可发。失败：模型服务失败保留消息并提供重试；识别到实际需要业务事实时转入澄清/查询，不编造答案。结束：结果明确标为通用说明，不生成不存在的证据引用。"}, {"id": "FL03", "name": "复杂问题到计划执行", "requirement": "PG04提出对象与分析需求 → 系统判断复杂任务 → PG07列必要缺项 → 用户补充并确认范围 → 系统形成带依赖的计划 → 按策略自动执行或等待确认 → PG05显示实际步骤、PG18同步树 → PG08可查工具 → 校验通过 → PG24报告引用产物 → 用户查看来源或追问。失败：用户取消澄清只保留上下文；计划不可执行须说明缺失工具；校验不通过进入FL10或FL11，不直接宣告完成。"}, {"id": "FL04", "name": "上传材料后研判", "requirement": "PG04/PG19选择文件 → 本地格式大小提示 → 服务端上传并安全检查 → 解析Processing → 成功显示预览和字段/页数 → 用户确认作为任务输入 → 发送需求 → 新任务引用object_id而非复制全量数据 → 完成后产物血缘可追溯。失败：上传中断可重新上传；解析错误可重试或移除；不支持格式仅保存或拒绝，不能标为已理解。取消上传清理临时对象但不删除已提交来源。"}, {"id": "FL05", "name": "资金流完整闭环", "requirement": "从PG04或PG13指定账户、时间和目的 → 确认身份与授权 → 计划采集、标准化、收支/对手分析、路径核验、报告 → 工具采集生成原始文件 → PG09核对来源覆盖和币种 → 查看重点交易及多跳路径 → 点击某交易打开PG22 → 加入报告或提出继续核查对手方 → 新对象授权后新Task → 生成资金报告。失败：某账户失败保留其他账户结果并标部分；交易方向不明先澄清；超出追踪层数明确截断。"}, {"id": "FL06", "name": "人员流完整闭环", "requirement": "输入对象及时间 → 多候选时PG07确认稳定标识 → 选择授权来源 → 采集事件 → PG10/PG23按时区和精度排序 → 用户检查冲突并展开两端来源 → 标记核验意见 → PG24生成轨迹及关系报告。失败：地点不能编码则列表展示；位置推断无充分来源时标待核验；不得在历史轨迹报告中写成当前确定位置。"}, {"id": "FL07", "name": "数据库问答完整闭环", "requirement": "输入统计问题 → PG07确认指标、时间和地域 → 读取真实schema与权限 → 生成并安全检查只读SQL → 执行、分页产物化 → 校验分母和去重 → PG11展示表图和口径 → 用户点击图表钻取 → 发起维度追问生成新查询版本 → 导出按FL14处理。失败：schema变动重新生成与校验；超时提示缩小范围；0行输出限定条件下未检出，不等同服务失败。"}, {"id": "FL08", "name": "授权申请与继续", "requirement": "动作准备执行 → 服务端发现范围缺口 → PG05权限卡说明阻断节点 → R1跳既有申请渠道，R2进入PG26提交 → PG27审批人查看并通过/拒绝 → 通知申请人 → 重新验证权限与任务有效性 → 用户确认继续 → 恢复安全检查点或重建相同目标的新attempt。拒绝：提供缩小范围、跳过可选步骤或结束任务；过期：重新申请；已终止任务收到通过：仅更新申请状态，不启动动作。"}, {"id": "FL09", "name": "停止中的竞态处理", "requirement": "PG05运行中用户点停止 → 弹层展示保留产物及外部不可撤回风险 → 确认发送幂等停止命令 → UI显示处理中且发送仍禁用 → 服务端取消未开始动作、阻止新派发、处理在途动作 → 返回权威快照 → 显示终止或已完成，释放执行锁 → 用户可发新任务。失败：停止超时不假装成功，可查询状态；若完成事件先于停止确认，以已完成事实为准并说明无需再停止。"}, {"id": "FL10", "name": "局部重试", "requirement": "PG08某工具失败 → 用户展开原因及已返回部分 → 对参数合法且可重试的动作点击重试 → 服务端复核权限、幂等和配置快照 → 记录attempt+1 → 成功后重新检查受影响依赖和结论 → 更新任务投影。失败：重复失败达到策略上限后停止自动尝试，提供改条件/重规划；权限失败走FL08，不当网络错误重试。"}, {"id": "FL11", "name": "重规划和部分结果", "requirement": "校验发现目标未覆盖或关键工具不可用 → PG07显示旧计划、失败原因、建议新计划及新增访问范围 → 用户接受、调整或只收取部分结果 → 接受后创建新plan_version并使旧待执行节点失效 → 复用有效已完成产物并标明复用 → 执行及复核 → 完整或部分结果报告。扩大范围必须重新授权；拒绝新计划可结束为部分成功或失败，取决于是否已有可用结果。"}, {"id": "FL12", "name": "结论到原始来源核验", "requirement": "PG05/PG24点击引用编号 → PG22校验访问权 → 展示原始对象和页/行定位 → 用户查看采集范围、转换链及同结论的反证 → 标记核验意见 → 回到原结论并保持阅读位置。失败：引用锚点失效提示定位不可用；对象撤权不显示缓存全文；原文件丢失将引用标异常并使依赖的复核状态需要重新检查。"}, {"id": "FL13", "name": "导图人工纠正", "requirement": "PG20选择实体或边 → PG21查看来源 → 点击补充/纠正 → 表单显示原值、来源及修改理由 → 提交版本校验 → 保存人工标注层 → 画布更新并保留选中对象 → 相关报告提示存在更新而非静默改写。失败：并发编辑冲突展示两版本供合并；合并实体必须检查稳定标识；置灰仅视觉弱化，不排除分析。"}, {"id": "FL14", "name": "报告复核和导出", "requirement": "任务产物就绪 → PG24生成报告 → 作者检查引用与缺口并编辑新版本 → R2提交冻结版本到复核 → 复核人通过或退回 → 修改后重新提交 → PG25选择导出范围、脱敏和用途 → 服务端重验权限生成导出任务 → PG28提示就绪 → 下载时再次鉴权并审计。R1无复核流时报告显示“未经人工复核”。失败：引用失效阻止生成“已复核完整报告”；导出失败保留报告；下载链接过期重新申请生成或续签。"}, {"id": "FL15", "name": "从正式案件发起研判", "requirement": "PG12筛选案件 → PG13核对案件上下文和成员权限 → 选资料及对象 → 发起搜索或专项任务 → PG05标明关联案件但仍属于超级搜索 → 执行生成成果 → 用户确认关联指定报告版本 → PG13成果列表显示来源与复核状态。失败：无案件系统接入不创建伪正式案件；更换案件需新上下文和授权，不能移动在途执行的归属。"}, {"id": "FL16", "name": "因事任务创建与采集", "requirement": "PG14新建 → PG15基本信息 → 添加已有/新实体、角色、立案分支和条件字段 → 选择可用采集工具 → 检查摘要并创建 → PG16展示未执行任务 → 用户确认采集 → 进入真实执行 → 图谱、文件与笔记关联同一任务 → 可继续研判与生成报告。失败：返回上一步保留输入；保存草稿不采集；第六实体被明确限制或按配置允许；申请中工具不被误算为已授权。"}, {"id": "FL17", "name": "案件串并到核验意见", "requirement": "PG17选择有权案件集合、时间及规则 → 系统生成候选对 → 用户查看实体/事件/资金关联和反证 → 标记待核验、建议关联或排除并说明 → 复核人员确认意见 → 生成带来源的串并研判意见 → 经独立授权后提交外部案件流程或导出。失败：数据不足保留待核验；无正式写回接口不出现“案件已合并”。"}, {"id": "FL18", "name": "断线刷新和恢复阅读", "requirement": "PG05接收SSE → 断网后显示连接中断且保留最后快照时间 → 用户刷新或网络恢复 → 鉴权 → 拉取最新快照及last_seq → 从游标订阅增量 → 去重和缺口检查 → 恢复任务树、消息、产物、草稿与阅读位置。失败：重放窗口过期全量重同步；鉴权过期走PG01；始终不通过重新发送原消息来“恢复任务”。"}, {"id": "FL19", "name": "工具配置发布与回滚", "requirement": "管理员PG30新建或编辑工具草稿 → 填schema、权限、副作用、凭据引用与超时 → 隔离测试 → PG31关联Agent/Toolkit并校验 → 受控发布生成版本 → 新任务使用新配置 → PG32观察失败率与耗时 → 必要时回滚到已验证版本。失败：测试或安全校验未过不得发布；回滚不能改变历史任务的工具版本记录；禁用工具时列出受影响在途任务。"}, {"id": "FL20", "name": "经验沉淀与下线", "requirement": "任务完成或人工纠错 → 生成候选经验，不自动全局生效 → PG33检查脱敏、适用条件和来源 → 运行回归样例与反例 → 审核通过发布版本 → 仅在授权且适用的新任务召回 → 记录命中与反馈 → 效果退化或发现泄露风险时下线并审计。失败：含真实案件敏感信息或评测不达标留在候选；下线不删除既往引用版本。"}, {"id": "FL21", "name": "暂停与安全恢复", "requirement": "支持检查点的任务运行 → 用户暂停 → 系统在安全动作边界落检查点并确认PAUSED → 用户可离开页面 → 返回查看权限、数据时效及外部动作状态 → 点击恢复 → 重新授权与兼容性检查 → 从明确的下一步恢复而非重放已完成动作。失败：检查点无效则提示重新执行或重规划；无检查点支持时该链路不可启用。"}, {"id": "FL22", "name": "组织切换与权限撤回", "requirement": "用户切换组织或后台撤销访问 → 前端关闭旧订阅、清除旧业务缓存 → 身份服务给出新权限 → 页面重新查询可见对象 → 旧深链统一无权限展示 → 历史通知与引用按新权限重验。运行中任务是否可继续由服务端授权策略决定，前端不自行判断；任何需要新访问的数据动作必须重验。失败：权限服务不可用默认阻止敏感新操作，不沿用不明有效性的权限。"}];
